css:
/* Home tablet framing: preserve all authored hero copy and separate art. */
@media (min-width: 761px) and (max-width: 1024px) {
  body:has(.home-hero) .home-hero,
  body:has(.home-hero) .home-hero__layout { height: auto; min-height: 480px; }
}

/* Feast-world grammar v1. Shared primitives, bounded to Home/progression rollout. */
body:has(.home-hero), body:has([data-progression-page]) {
  --feast-paper: var(--cream-100);
  --feast-paper-light: var(--cream-50);
  --feast-ink: var(--navy-900);
  --feast-frame: var(--gold-400);
  --feast-radius: 16px;
  --feast-depth: 0 3px 0 rgb(91 42 27 / 14%), 0 8px 22px rgb(30 16 13 / 18%);
  --feast-display: Georgia, 'Times New Roman', serif;
}
body:has(.home-hero) .site-header, body:has([data-progression-page]) .site-header {
  background: linear-gradient(180deg, var(--chocolate-800), var(--chocolate-950));
  border-bottom: 2px solid var(--gold-500);
}
body:has(.home-hero) .site-brand, body:has([data-progression-page]) .site-brand {
  color: var(--cream-100); text-shadow: 0 2px var(--chocolate-950); letter-spacing: -.04em;
}
body:has(.home-hero) :is(.section-heading, .discovery-card h3, .home-discovery-card h3),
[data-progression-page] :is(h1,h2,h3) { font-family: var(--feast-display); color: var(--feast-ink); }
body:has(.home-hero) :is(.home-discovery-card,.discovery-card,.today-panel),
[data-progression-page] :is(.progression-hero,.progression-section,.progression-daily,.progression-controls,.progression-nav),
.feast-journey-links { background: linear-gradient(145deg,var(--feast-paper-light),var(--feast-paper)); border: 1px solid var(--feast-frame); border-radius: var(--feast-radius); box-shadow: var(--feast-depth); }
body:has(.home-hero) .button-link--primary, [data-progression-page] .button-link--primary {
  background: linear-gradient(var(--pink-600),var(--pink-700)); border: 1px solid var(--pink-700); box-shadow: inset 0 1px rgb(255 255 255 / 40%),0 3px 0 rgb(111 15 53 / 22%); color: white;
}
body:has(.home-hero) .button-link--secondary, [data-progression-page] .button-link--secondary {
  background: var(--feast-paper-light); color: var(--feast-ink); border: 1px solid var(--gold-600);
}
.feast-journey-links { display:flex; flex-wrap:wrap; gap:6px; padding:8px; margin-block:10px; box-shadow:none; }
.feast-journey-links .button-link { min-height:44px; padding:8px 10px; font-size:.82rem; flex:1 1 auto; justify-content:center; }
.feast-progress-note,.feast-quest-prompt { font-size:.82rem; line-height:1.45; color:var(--chocolate-800); margin:8px 0; }
.feast-progress-note { padding:6px 8px; border-left:3px solid var(--gold-500); background:var(--feast-paper); }
.feast-progress-note strong { color:var(--feast-ink); }
@media(min-width:961px) {
  body:has(.home-hero) .toadal-companion[data-minimized='true'], body:has(.progression-page) .toadal-companion[data-minimized='true'] { width:100px; }
  body:has(.home-hero) .toadal-companion[data-minimized='true'] .companion-toggle, body:has(.progression-page) .toadal-companion[data-minimized='true'] .companion-toggle { width:100px; height:110px; min-width:44px; min-height:44px; }
  body:has(.home-hero) .toadal-companion[data-minimized='true'] .companion-image, body:has(.progression-page) .toadal-companion[data-minimized='true'] .companion-image { width:100px; height:110px; max-height:110px; object-fit:contain; }
}
/* Existing live Home summary; no illustrative/fabricated balances. */
body:has(.home-hero) [data-progression-page] { width:100%; margin:0; padding:0; }
#feast-pass .home-section-inner { width:100%; max-width:none; height:auto; }
#feast-pass .feast-pass-panel { height:auto; max-height:none; overflow:visible; }
#feast-pass .home-feast-pass-panel { width:100%; min-height:0; margin:0; padding:16px; border:1px solid var(--feast-frame); border-radius:var(--feast-radius); background:linear-gradient(145deg,var(--feast-paper-light),var(--feast-paper)); color:var(--chocolate-800); box-shadow:var(--feast-depth); display:block; }
#feast-pass .feast-pass-copy { width:100%; max-width:none; }
#feast-pass .home-feast-pass-panel .pass-emblem { display:none; }
#feast-pass .home-feast-pass-panel :is(.section-kicker,.section-lede,.home-pass-storage-status,dt) { color:var(--chocolate-800); }
#feast-pass .home-feast-pass-panel .section-heading { color:var(--feast-ink); font-size:1.65rem; margin:4px 0 8px; }
#feast-pass .section-lede { font-size:.8rem; line-height:1.45; }
#feast-pass .home-pass-metrics { gap:6px; margin:10px 0; }
#feast-pass .home-pass-metrics > div { background:var(--feast-paper-light); border:1px solid var(--gold-400); padding:5px 8px; }
#feast-pass .home-pass-metrics dd { color:var(--chocolate-800); }
#feast-pass .home-pass-storage-status { font-size:.72rem; }
body:has(.home-hero) #feast-pass .home-section-inner { padding:0; width:100%; }
body:has(.home-hero) #feast-pass .home-feast-pass-panel { min-height:0; height:auto; padding:14px; }
body:has(.home-hero) #browser-games-intro .home-section-inner { padding:10px 14px; width:100%; }
body:has(.home-hero) :is(#discovery,#interactive-discovery,#app) .home-section-inner { padding:12px 0; width:100%; }
#feast-pass .feast-journey-links { padding:0; border:0; background:none; }
#feast-pass .feast-journey-links .button-link { flex:1 1 30%; min-height:44px; padding:6px; font-size:.73rem; }
/* Reuse progression family markup: journey first, metrics/days/collection in dense bands. */
body:has(.progression-page) main > .section { width:100%; max-width:none; padding:16px 0 24px; }
.progression-page { width:min(calc(100% - 32px),1200px); padding:0 0 24px; }
[data-progression-page] .progression-hero { padding:22px; }
[data-progression-page] .progression-hero h1 { font-size:clamp(2.2rem,5vw,3.7rem); margin-bottom:10px; }
[data-progression-page] .progression-lede { max-width:76ch; font-size:1rem; }
[data-progression-page] .progression-truth-note { max-width:90ch; padding:10px 12px; font-size:.82rem; }
[data-progression-page] :is(.progression-section,.progression-daily) { margin-top:14px; padding:18px; }
[data-progression-page] .progression-section-heading { margin-bottom:12px; }
[data-progression-page] :is(.progression-section-heading h2,.progression-daily h2) { font-size:1.6rem; }
[data-progression-page] .progression-stat-grid { gap:8px; margin:0; }
[data-progression-page] .progression-stat { padding:10px; background:var(--feast-paper-light); border-color:var(--gold-400); }
[data-progression-page] .progression-stat dd { font-size:1.5rem; }
[data-progression-page] .progression-daily-track { list-style:none; padding:0; display:flex; flex-wrap:wrap; gap:6px; }
[data-progression-page] .progression-daily-track li { padding:8px 10px; border:1px solid var(--gold-400); border-radius:10px; background:var(--feast-paper-light); font-size:.8rem; }
[data-progression-page] .progression-daily-track [data-completed='true'] { background:var(--gold-400); color:var(--chocolate-950); }
[data-progression-page] .progression-daily-track [aria-current='step'] { outline:2px solid var(--pink-700); outline-offset:2px; }
[data-progression-page] .detail-breadcrumb { background:var(--feast-paper); border-radius:10px; padding:8px 12px; width:fit-content; }
[data-progression-page] :is(.progression-empty,.progression-list-item) { border-color:var(--gold-400); }
@media(min-width:1180px) {
  body:has(.home-hero) main { grid-template-rows:auto 96px auto auto auto auto auto auto; grid-template-areas:'hero hero' 'games-intro pass' 'games pass' 'discovery discovery' 'today today' 'interactive interactive' 'app next' 'companion companion'; }
  body:has(.home-hero) #discovery { grid-row:4; }
  body:has(.home-hero) #today { grid-row:5; }
  body:has(.home-hero) #interactive-discovery { grid-row:6; }
  .progression-page[data-progression-page='feast-pass'] { display:grid; grid-template-columns:minmax(0,1.35fr) minmax(0,1fr); gap:12px; }
  .progression-page[data-progression-page='feast-pass'] > * { grid-column:1 / -1; margin:0; }
  .progression-page[data-progression-page='feast-pass'] > .progression-section:has([data-progression-stat='level']) { grid-column:1; }
  .progression-page[data-progression-page='feast-pass'] > .progression-daily { grid-column:2; grid-row:4; display:flex; flex-direction:column; align-items:flex-start; justify-content:space-between; }
  .progression-page[data-progression-page='feast-pass'] .progression-stat-grid { grid-template-columns:repeat(4,minmax(0,1fr)); }
  body:has(.home-hero) main { row-gap:10px; }
  body:has(.home-hero) #browser-games .studio-game-card { padding:10px; }
  body:has(.home-hero) #browser-games .studio-game-card { display:flex; flex-direction:column; }
  body:has(.home-hero) #browser-games .studio-game-card .chip { align-self:flex-start; margin-top:auto; }
  body:has(.home-hero) #browser-games .studio-game-card p { font-size:.76rem; line-height:1.4; }
  body:has(.home-hero) #browser-games .studio-game-card h3 { font-size:1rem; }
  body:has(.home-hero) #feast-pass { background:none; border:0; box-shadow:none; }
  body:has(.home-hero) #discovery .discovery-card { min-height:0; padding:12px; }
  body:has(.home-hero) #discovery .discovery-card > p:not(.section-kicker) { font-size:.78rem; }
  body:has(.home-hero) #discovery .discovery-heading { margin-bottom:10px; padding:0; }
  body:has(.home-hero) #discovery .discovery-heading .section-heading { max-width:none; font-size:1.65rem; }
  body:has(.home-hero) #discovery .discovery-card { box-shadow:none; background:var(--feast-paper-light); }
  body:has(.home-hero) #discovery .character-figure img { max-height:86px; }
  body:has(.home-hero) #interactive-discovery { padding:0 14px; }
  body:has(.home-hero) .home-discovery-section { padding:12px 0; }
}
@media(min-width:601px) and (max-width:1179px) {
  body:has(.home-hero) main { width:calc(100% - 24px); margin:auto; }
  body:has(.home-hero) .shell { width:100%; }
  body:has(.home-hero) #browser-games { grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px !important; padding:12px; }
  body:has(.home-hero) #browser-games .studio-game-card img { height:120px; }
  body:has(.home-hero) #feast-pass { padding:0; }
  body:has(.home-hero) .home-discovery-grid { grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; }
  body:has(.home-hero) .home-discovery-card { min-height:0; padding:14px; }
  body:has(.home-hero) #discovery .discovery-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
  body:has(.home-hero) #discovery .discovery-card--stories { grid-column:1 / -1; }
  body:has(.home-hero) #discovery .discovery-card { min-height:0; padding:14px; }
  body:has(.home-hero) #discovery .world-art { height:150px; max-height:150px; }
  body:has(.home-hero) #discovery .character-figure img { max-height:90px; }
  body:has(.home-hero) #discovery .stories-art--illustrated { min-height:120px; max-height:150px; }
  body:has(.home-hero) :is(.portal-discovery-art,.golden-block-art) { max-width:150px; margin-inline:auto; }
  body:has(.home-hero) #discovery .discovery-grid { gap:10px; }
}
@media(max-width:600px) {
  body:has(.home-hero) main { width:calc(100% - 20px); margin:auto; }
  body:has(.home-hero) .shell { width:100%; }
  body:has(.home-hero) .home-hero__title { font-size:2.25rem; max-width:12ch; }
  body:has(.home-hero) #browser-games { grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px !important; padding:10px; }
  body:has(.home-hero) #browser-games .studio-game-card { padding:8px; min-height:0; }
  body:has(.home-hero) #browser-games .studio-game-card img { height:92px; object-fit:cover; }
  body:has(.home-hero) #browser-games .studio-game-card h3 { font-size:.95rem; line-height:1.15; }
  body:has(.home-hero) #browser-games .studio-game-card p { font-size:.78rem; line-height:1.4; }
  body:has(.home-hero) #feast-pass { padding:0; }
  body:has(.home-hero) :is(.home-discovery-card,.discovery-card) { padding:12px; min-height:0; }
  body:has(.home-hero) :is(.portal-discovery-art,.golden-block-art) { max-width:132px; margin:8px auto; }
  body:has(.home-hero) .home-discovery-section { padding:12px; }
  body:has(.home-hero) .home-discovery-heading .section-heading { font-size:1.6rem; }
  body:has(.home-hero) .home-discovery-card .discovery-action-status { min-height:0; }
  body:has(.home-hero) .home-discovery-card { display:grid; grid-template-columns:minmax(0,1fr) 78px; gap:8px; }
  body:has(.home-hero) .home-discovery-card__heading { grid-column:1 / -1; }
  body:has(.home-hero) .home-discovery-card :is(.portal-discovery-art,.golden-block-art) { grid-column:2; grid-row:2 / span 2; width:78px; max-width:78px; margin:0; align-self:center; }
  body:has(.home-hero) .home-discovery-card :is(.portal-discovery-button,.golden-block-hit-button) { grid-column:1; grid-row:2; width:100%; }
  body:has(.home-hero) .home-discovery-card :is(.discovery-action-status,.home-candy-button,.home-candy-reveal) { grid-column:1 / -1; }
  body:has(.home-hero) .home-discovery-grid { gap:12px; }
  body:has(.home-hero) #discovery .world-art { height:130px; }
  [data-progression-page] .progression-hero { padding:18px; }
  [data-progression-page] :is(.progression-section,.progression-daily,.progression-controls) { padding:14px; }
  [data-progression-page] .progression-muted { max-width:none; text-align:left; }
  [data-progression-page] .progression-nav a { min-height:44px; }
  .feast-journey-links .button-link { flex:1 1 44%; }
}
/* The world object IS its control, not decoration above an activation button. */
body:has(.home-hero) .home-discovery-card {
  display:grid; grid-template-columns:minmax(0,1fr) 144px; gap:8px 14px; align-content:start;
}
body:has(.home-hero) .home-discovery-card__heading { grid-column:1; grid-row:1; }
body:has(.home-hero) .home-discovery-card .discovery-action-status { grid-column:1; grid-row:2; margin:0; }
body:has(.home-hero) .home-discovery-card :is(.home-candy-button,.home-candy-reveal) { grid-column:1 / -1; }
body:has(.home-hero) .home-discovery-card .feast-art-control {
  grid-column:2; grid-row:1 / span 2; width:144px; max-width:144px; min-width:44px; min-height:44px;
  aspect-ratio:1; margin:0; padding:0; border:0; appearance:none; cursor:pointer; touch-action:manipulation; align-self:center;
}
body:has(.home-hero) .portal-discovery-art.feast-art-control { display:grid; place-items:center; background:transparent; box-shadow:none; }
body:has(.home-hero) .golden-block-art.feast-art-control { display:block; border-radius:16px; }
body:has(.home-hero) .feast-art-control:focus-visible { outline:3px solid var(--pink-700); outline-offset:5px; }
body:has(.home-hero) .feast-art-control:disabled { cursor:default; }
body:has(.home-hero) .feast-art-control:not(:disabled):active { transform:scale(.97); }
body:has(.home-hero) #today .today-panel .today-actions.daily-chest-actions {
  grid-template-columns:168px minmax(0,1fr); min-width:0; gap:8px 14px;
}
body:has(.home-hero) #today .today-panel .daily-chest-actions .daily-chest-button.feast-art-control {
  grid-column:1; grid-row:1 / span 2; display:grid; place-items:center; width:168px; min-width:44px; min-height:168px;
  margin:0; padding:0; border:0; border-radius:18px; background:transparent; box-shadow:none; appearance:none; cursor:pointer; touch-action:manipulation;
}
body:has(.home-hero) #today .today-panel .daily-chest-actions .daily-chest-scene { width:168px; height:168px; }
body:has(.home-hero) #today .daily-chest-sprite { background-color:transparent; }
body:has(.home-hero) #today .daily-chest-button.feast-art-control:disabled { cursor:default; }
body:has(.home-hero) #today .daily-chest-button .feast-control-label {
  position:absolute!important; width:1px!important; height:1px!important; padding:0!important; margin:-1px!important;
  overflow:hidden!important; clip-path:inset(50%)!important; white-space:nowrap!important; border:0!important;
}
@media(max-width:600px) {
  body:has(.home-hero) .home-discovery-card { grid-template-columns:minmax(0,1fr) 112px; gap:8px 12px; }
  body:has(.home-hero) .home-discovery-card .feast-art-control { width:112px; max-width:112px; }
  body:has(.home-hero) #today .today-panel .today-actions.daily-chest-actions { grid-template-columns:160px minmax(0,1fr); }
  body:has(.home-hero) #today .today-panel .daily-chest-actions .daily-chest-button.feast-art-control { width:160px; min-height:160px; }
  body:has(.home-hero) #today .today-panel .daily-chest-actions .daily-chest-scene { width:160px; height:160px; }
  body:has(.home-hero) #today .today-panel .daily-chest-actions .daily-chest-help { grid-column:2; max-width:none; font-size:.76rem; text-align:left; }
  body:has(.home-hero) #today .today-panel .daily-chest-actions > a.button-link { grid-column:2; min-height:44px; white-space:normal; }
}

/* Feast-world grammar rollout: reuse native journey/card markup, only these 3 pages. */
.feast-journey-page .progression-hero { padding:20px; }
.feast-journey-page .progression-hero h1 { font-size:clamp(2.1rem,4.2vw,3.3rem); }
.feast-journey-page .progression-lede { max-width:85ch; }
.feast-journey-page .progression-truth-note { max-width:90ch; margin-top:12px; }
.feast-journey-page .feast-journey-links { margin:12px 0; gap:6px; padding:8px; box-shadow:none; }
.feast-journey-page .feast-journey-links a { flex:1 1 auto; min-height:44px; justify-content:center; text-decoration:none; }
.feast-journey-page .feast-journey-links a[aria-current='page'] { background:var(--pink-700); color:white; border-color:var(--pink-700); }
.feast-journey-page .progression-storage { margin:8px 0 12px; font-size:.82rem; }
.feast-journey-page :is([data-progression-quest-list],[data-progression-reward-list]) { padding:0; border:0; border-radius:0; background:none; }
.feast-journey-page [data-progression-quest-list] { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }
.feast-journey-page [data-progression-quest-list] > [role='group'] { min-width:0; padding:14px; border:1px solid var(--feast-frame); border-radius:var(--feast-radius); background:var(--feast-paper-light); }
.feast-journey-page [data-progression-quest-list] > [aria-label='Exploration quests'] { grid-column:1 / -1; }
.feast-journey-page [data-progression-quest-list] > [role='group'] h3 { font-family:var(--feast-display); font-size:1.3rem; margin:0 0 10px; }
.feast-journey-page [data-progression-quest-list] [role='list'] { display:grid; gap:10px; }
.feast-journey-page [data-progression-reward-list] { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; }
.feast-journey-page :is([data-progression-quest-list],[data-progression-reward-list]) [role='listitem'] { min-width:0; display:flex; flex-direction:column; align-items:flex-start; padding:12px; border:1px solid var(--gold-400); border-radius:12px; background:var(--feast-paper); font-size:.88rem; }
.feast-journey-page :is([data-progression-quest-list],[data-progression-reward-list]) [role='listitem'] > strong { color:var(--feast-ink); font-size:.95rem; }
.feast-journey-page :is([data-progression-quest-list],[data-progression-reward-list]) [role='listitem'] p { margin:6px 0 10px; line-height:1.5; }
.feast-journey-page :is([data-progression-quest-list],[data-progression-reward-list]) [role='listitem'] > :is(button,a) { display:inline-flex; align-items:center; justify-content:center; min-height:44px; max-width:100%; margin-top:auto; padding:8px 12px; border:1px solid var(--gold-600); border-radius:999px; font:inherit; font-weight:700; text-align:center; text-decoration:none; cursor:pointer; background:var(--feast-paper-light); color:var(--feast-ink); }
.feast-journey-page :is([data-progression-quest-list],[data-progression-reward-list]) [role='listitem'] > button { background:var(--pink-700); color:white; border-color:var(--pink-700); }
.feast-journey-page :is(button,a,input):focus-visible { outline:3px solid var(--pink-700); outline-offset:3px; }
.feast-journey-page [role='listitem']:has(> button) { border-color:var(--gold-600); }
.feast-journey-page .guest-profile-identity { display:flex; align-items:center; gap:14px; width:fit-content; max-width:100%; margin:14px 0; padding:12px; border:1px solid var(--feast-frame); border-radius:var(--feast-radius); background:var(--feast-paper); }
.feast-journey-page .guest-profile-avatar { display:grid; place-items:center; flex:0 0 56px; width:56px; height:56px; border:2px solid var(--gold-600); border-radius:50%; background:var(--gold-400); color:var(--chocolate-950); font-size:1.6rem; font-weight:900; }
.feast-journey-page .guest-profile-identity :is(h2,p) { margin:0; }
.feast-journey-page .guest-profile-identity h2 { font-family:var(--feast-display); font-size:1.45rem; line-height:1.2; margin:4px 0; }
.feast-journey-page .progression-empty:not([data-progression-quest-list]):not([data-progression-reward-list]) { padding:12px; }
.feast-journey-page label:has([data-site-motion-toggle]) { display:flex; align-items:center; gap:10px; min-height:44px; padding:6px 0; cursor:pointer; }
.feast-journey-page .progression-controls { box-shadow:none; padding:14px; }
.feast-journey-page .progression-controls button { min-height:44px; }
@media(min-width:961px) {
  .feast-journey-page [data-progression-quest-list] > [aria-label='Exploration quests'] > [role='list'] { grid-template-columns:repeat(3,minmax(0,1fr)); }
  .feast-journey-page[data-progression-page='profile'] { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }
  .feast-journey-page[data-progression-page='profile'] > * { grid-column:1 / -1; margin:0; }
  .feast-journey-page[data-progression-page='profile'] > .progression-section:not(.feast-profile-summary) { grid-column:auto; }
