      if (speech.textContent !== copy) speech.textContent = copy;
    }
    function persistPreference() {
      try { window.localStorage.setItem(storageKey, minimized ? 'true' : 'false'); } catch (error) {}
    }
    function persistHiddenPreference() {
      try { window.localStorage.setItem(hiddenStorageKey, hidden ? 'true' : 'false'); } catch (error) {}
    }
    function setHidden(value, returnFocus) {
      hidden = !!value;
      lastToggleClickAt = 0;
      clearTouchedContext();
      persistHiddenPreference();
      render(false);
      if (returnFocus) {
        window.requestAnimationFrame(function () {
          var target = hidden ? restoreButton : toggle;
          if (target && typeof target.focus === 'function') {
            try { target.focus({ preventScroll: true }); } catch (error) { target.focus(); }
          }
        });
      }
    }

    hideButton.addEventListener('click', function (event) {
      event.preventDefault();
      event.stopPropagation();
      setHidden(true, event.detail === 0);
    });

    restoreButton.addEventListener('click', function (event) {
      setHidden(false, event.detail === 0);
    });

    toggle.addEventListener('click', function (event) {
      if (hidden) return;
      var pointerClick = lastInput === 'pointer' && event.detail > 0;
